    h,w=len(g),len(g[0])
    # Recolor complete monochrome separator lines.
    for r in range(h):
        vals=set(g[r])
        if len(vals)==1:
            c=next(iter(vals))
            if c != 7:
                g[r]=[2]*w
    for c in range(w):
        vals={grid[r][c] for r in range(h)}
        if len(vals)==1:
            v=next(iter(vals))
            if v != 7:
                for r in range(h): g[r][c]=2
    return g

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(h):
        if all(x==9 for x in grid[r]): g[r]=[2]*w
    for c in range(w):
        if all(grid[r][c]==9 for r in range(h)):
            for r in range(h): g[r][c]=2
    return g
